// Skip PRs already reviewed at their current head sha (workflow static data).
const store = $getWorkflowStaticData('global');
const reviewed = store.reviewed || {};
const out = [];
for (const item of $input.all()) {
  const pr = item.json;
  const key = String(pr.number);
  if (reviewed[key] === pr.head.sha) continue;
  out.push({ json: pr });
}
return out;

// Record the reviewed head sha so the next run skips it.
const store = $getWorkflowStaticData('global');
store.reviewed = store.reviewed || {};
for (const item of $input.all()) {
  const pr = $('List open PRs').item.json;
  store.reviewed[String(pr.number)] = pr.head.sha;
}
return $input.all();
